    private static int CreateTrampoline(nint src, ulong offset, uint size, nint* buf)
    {
        try
        {
            if (Gst.GObject.Object.TryGetInterned(src) is not BaseSrc managed)
            {
                return (int)(ChainUpCreate(src, offset, size, buf));
            }

            nint bufEntry = *buf;
            Gst.Buffer? bufValue = bufEntry == nint.Zero ? null : Gst.Buffer.Borrow(bufEntry);

            try
            {
                Gst.FlowReturn result = managed.OnCreate(offset, size, ref bufValue);

                if (result == Gst.FlowReturn.Ok)
                {
                    nint bufHandle = bufValue is null ? nint.Zero : bufValue.Handle;
                    if (bufHandle != nint.Zero && bufHandle != bufEntry)
                    {
                        Gst.GstNative.MiniObjectRef(bufHandle);
                    }
                    *buf = bufHandle;
                }
                return (int)(result);
            }
            finally
            {
                bufValue?.Dispose();
            }
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
            return (int)Gst.FlowReturn.Error;
        }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int AllocTrampoline(nint src, ulong offset, uint size, nint* buf)
    {
        try
        {
            if (Gst.GObject.Object.TryGetInterned(src) is not BaseSrc managed)
            {
                return (int)(ChainUpAlloc(src, offset, size, buf));
            }

            Gst.Buffer? bufValue = null;

            try
            {
                Gst.FlowReturn result = managed.OnAlloc(offset, size, out bufValue);

                if (result == Gst.FlowReturn.Ok)
                {
                    nint bufHandle = bufValue is null ? nint.Zero : bufValue.Handle;
                    if (bufHandle != nint.Zero)
                    {
                        Gst.GstNative.MiniObjectRef(bufHandle);
                    }
                    *buf = bufHandle;
                }
                return (int)(result);
            }
            finally
            {
                bufValue?.Dispose();
            }
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
            return (int)Gst.FlowReturn.Error;
        }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int FillTrampoline(nint src, ulong offset, uint size, nint buf)
    {
        try
        {
            if (Gst.GObject.Object.TryGetInterned(src) is not BaseSrc managed)
            {
                return (int)(ChainUpFill(src, offset, size, buf));
            }

            using Gst.Buffer? bufValue = buf == nint.Zero ? null : Gst.Buffer.Borrow(buf);
            return (int)(managed.OnFill(offset, size, bufValue!));
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
            return (int)Gst.FlowReturn.Error;
        }
    }
}
